#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# W009 dot3 kit: FCMP++ wallet tx-build speed on the Q6600, the dot3-prep branch as built.
#   wallet A/B: monero-wallet-rpc-dot2 (monerodato.2) vs monero-wallet-rpc-dot3 (a static build of the dot3-prep branch:
#      the constant-time multiexp uses Straus(4) at every length), each on its own copy of a wallet COPY, against your local daemon. ROUNDS rounds,
#      arm order alternating; per arm and round a 1-input warm-up (not counted) then N_LIST. sweep_all with do_not_relay
#      only: nothing is relayed. The wallet copies are deleted at the end.
# usage: I_AM_A_COPY=yes DAEMON=127.0.0.1:<rpc port> WALLET_DIR=<dir holding a COPY of a wallet> WALLET_NAME=<file name> \
#          [WALLET_PASSWORD=...] [N_LIST=8,32] [ROUNDS=3] bash run_kit.sh
# Writes ./w009-dot3-results-<time>/ and a tar of it.
set -u
: "${DAEMON:?}" "${WALLET_DIR:?}" "${WALLET_NAME:?}"
[ "${I_AM_A_COPY:-}" = yes ] || { echo "refusing: set I_AM_A_COPY=yes; WALLET_DIR must hold a COPY of a wallet"; exit 2; }
here=$(cd "$(dirname "$0")" && pwd)
N_LIST=${N_LIST:-8,32}; ROUNDS=${ROUNDS:-3}
R=$PWD/w009-dot3-results-$(date -u +%Y%m%dT%H%M%SZ); mkdir -p "$R"; chmod 700 "$R"
lg() { echo "$(date -u +%FT%TZ) $*" | tee -a "$R/log.txt"; }
lg "start; host: nproc $(nproc); $(grep -m1 'model name' /proc/cpuinfo); $(awk '/^(MemTotal|MemAvailable)/ {printf "%s %s kB; ", $1, $2}' /proc/meminfo); load $(cut -d' ' -f1-3 /proc/loadavg)"
(cd "$here" && sha256sum -c SHA256SUMS) > "$R/sums.txt" 2>&1 || { lg "SHA256SUMS mismatch, stopping"; exit 2; }
W=$R/wallets; mkdir -p "$W/dot2" "$W/dot3"; chmod -R 700 "$W"
for a in dot2 dot3; do cp -p "$WALLET_DIR/$WALLET_NAME" "$WALLET_DIR/$WALLET_NAME.keys" "$W/$a/" || { lg "cannot copy the wallet"; exit 2; }; done
P_dot2=38486; P_dot3=38487
for a in dot2 dot3; do
  port=P_$a
  "$here/monero-wallet-rpc-$a" --testnet --wallet-dir "$W/$a" --daemon-address "$DAEMON" --trusted-daemon --rpc-bind-ip 127.0.0.1 \
    --rpc-bind-port ${!port} --disable-rpc-login --non-interactive --log-file "$R/wallet-rpc-$a.log" --log-level '*:WARNING,perf.*:DEBUG' > /dev/null 2>&1 &
  echo $! > "$R/pid_$a"
done
for a in dot2 dot3; do port=P_$a; for i in $(seq 1 120); do curl -s -m 3 http://127.0.0.1:${!port}/json_rpc -d '{"jsonrpc":"2.0","id":0,"method":"get_version"}' | grep -q result && break; sleep 1; done; done
cleanup() { kill $(cat "$R"/pid_* 2> /dev/null) 2> /dev/null; sleep 2; rm -rf "${W:?}"; lg "wallet copies deleted"; }
trap cleanup EXIT
lg "wallet A/B: N_LIST $N_LIST, ROUNDS $ROUNDS"
for a in dot2 dot3; do port=P_$a; python3 -I "$here/q6600_drive.py" ${!port} $(cat "$R/pid_$a") "$WALLET_NAME" $a "$R/prep_$a.csv" 1 prep >> "$R/log.txt" 2>&1 || { lg "prep failed for $a"; exit 1; }; done
for r in $(seq 1 "$ROUNDS"); do
  if [ $((r % 2)) = 1 ]; then order="dot3 dot2"; else order="dot2 dot3"; fi
  for a in $order; do
    port=P_$a
    python3 -I "$here/q6600_drive.py" ${!port} $(cat "$R/pid_$a") "$WALLET_NAME" $a "$R/warmup.csv" 1 >> "$R/log.txt" 2>&1
    python3 -I "$here/q6600_drive.py" ${!port} $(cat "$R/pid_$a") "$WALLET_NAME" $a "$R/wallet.csv" "$N_LIST" 2>&1 | sed "s/^/r$r /" | tee -a "$R/log.txt"
  done
done
lg "done"; trap - EXIT; cleanup
tar czf "$R.tar.gz" -C "$(dirname "$R")" "$(basename "$R")"; lg "results: $R.tar.gz"
